import type { Difficulty } from '../src/questions/types';

export interface SleeveSpec {
  slug: string;
  prompt: string;
  correct: string;
  incorrect: string[];
  difficulty: Difficulty;
  artist: string;
  term: string;
  /** When search is drowned by tributes, lookup this GB collection id. */
  collectionId?: number;
  /**
   * The song played halfway through the question as a clue, by its title on
   * this album. Absent means the sleeve plays silent, as it always did. Never a
   * song whose title names the album — `sleeve-song.ts` refuses those.
   * See docs/decisions/sleeves-song.md.
   */
  song?: string;
  /** Both from `npm run tune-audit -- --pack sleeves`, not guessed. */
  previewStart?: number;
  previewSeconds?: number;
}

